// Writes test/fixtures/handbook.pdf: a two-page text PDF with one section per page.
// Generated by hand instead of with a PDF library so the fixture needs no dependency
// and the exact text is known to the tests.
import { writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

const pages = [
  [
    "1 Annual leave",
    "Every employee of Northwind receives 27 days of paid annual leave per year.",
    "Unused leave can be carried over until the end of March of the next year.",
  ],
  [
    "2 Expense claims",
    "Expense claims are submitted through the finance portal within 30 days.",
    "Receipts above 50 euros must be attached as a scanned copy.",
  ],
];

function escapeText(s) {
  return s.replace(/[\\()]/g, (c) => "\\" + c);
}

function pageStream(lines) {
  const ops = ["BT", "/F1 14 Tf", "72 720 Td", "18 TL"];
  for (const line of lines) ops.push(`(${escapeText(line)}) Tj T*`);
  ops.push("ET");
  return ops.join("\n");
}

export function buildPdf() {
  const objects = [];
  const pageIds = pages.map((_, i) => 4 + i * 2);
  objects[1] = "<< /Type /Catalog /Pages 2 0 R >>";
  objects[2] = `<< /Type /Pages /Kids [${pageIds.map((id) => `${id} 0 R`).join(" ")}] /Count ${pages.length} >>`;
  objects[3] = "<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>";
  pages.forEach((lines, i) => {
    const pageId = pageIds[i];
    const stream = pageStream(lines);
    objects[pageId] =
      `<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] ` +
      `/Resources << /Font << /F1 3 0 R >> >> /Contents ${pageId + 1} 0 R >>`;
    objects[pageId + 1] = `<< /Length ${Buffer.byteLength(stream)} >>\nstream\n${stream}\nendstream`;
  });

  let out = "%PDF-1.4\n";
  const offsets = [];
  for (let id = 1; id < objects.length; id++) {
    offsets[id] = Buffer.byteLength(out);
    out += `${id} 0 obj\n${objects[id]}\nendobj\n`;
  }
  const xrefAt = Buffer.byteLength(out);
  out += `xref\n0 ${objects.length}\n0000000000 65535 f \n`;
  for (let id = 1; id < objects.length; id++) {
    out += `${String(offsets[id]).padStart(10, "0")} 00000 n \n`;
  }
  out += `trailer\n<< /Size ${objects.length} /Root 1 0 R >>\nstartxref\n${xrefAt}\n%%EOF\n`;
  return Buffer.from(out, "latin1");
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const target = new URL("./handbook.pdf", import.meta.url);
  writeFileSync(target, buildPdf());
  console.log(`[fixtures] wrote ${fileURLToPath(target)}`);
}
